int parse_time(const std::string& s) {
    int h = 0, m = 0, sec = 0;
    int cnt = 0;
    for (char c : s) if (c == ':') cnt++;
    if (cnt == 2) {
        sscanf(s.c_str(), "%d:%d:%d", &h, &m, &sec);
        return h*3600 + m*60 + sec;
    } else {
        sscanf(s.c_str(), "%d:%d", &m, &sec);
        return m*60 + sec;
    }
}

std::string fmt_time(int seconds) {
    if (seconds < 0) return "?";
    int h = seconds / 3600;
    int m = (seconds % 3600) / 60;
    int s = seconds % 60;
    char buf[32];
    if (h > 0)
        snprintf(buf, sizeof(buf), "%d:%02d:%02d", h, m, s);
    else
        snprintf(buf, sizeof(buf), "%d:%02d", m, s);
    return buf;
}

std::string fmt_pace(int secs_per_mile) {
    if (secs_per_mile <= 0) return "?";
    return fmt_time(secs_per_mile) + "/mi";
}

// Linearly interpolate an integer table column given fractional index.
static int lerp(int a, int b, double t) {
    return (int)std::round(a + t * (b - a));
}


int goal_to_5k(int goal_seconds, const std::string& distance) {
    int col;
    if (distance == "5k")       col = 0;
    else if (distance == "10k") col = 1;
    else if (distance == "half") col = 2;
    else if (distance == "marathon") col = 3;
    else throw std::runtime_error("unknown distance: " + distance);

    const int (*t)[4] = race_table;
    int nrows = race_table_rows;

    // Find surrounding rows by column `col`
    // First collect the column
    for (int i = 0; i < nrows - 1; i++) {
        int a = t[i][col], b = t[i+1][col];
        if (goal_seconds >= a && goal_seconds <= b) {
            double frac = (double)(goal_seconds - a) / (b - a);
            return lerp(t[i][0], t[i+1][0], frac);
        }
    }
    // Clamp
    if (goal_seconds <= t[0][col]) return t[0][0];
    return t[nrows-1][0];
}

Paces lookup_paces(int sk5_seconds) {
    Paces p{};
    p.sk5_sec = sk5_seconds;

    auto interp = [&](const int* table, int nrows, int ncols, int col) -> int {
        for (int i = 0; i < nrows - 1; i++) {
            int a = table[i * ncols], b = table[(i+1) * ncols];
            if (sk5_seconds >= a && sk5_seconds <= b) {
                double frac = (double)(sk5_seconds - a) / (b - a);
                return lerp(table[i*ncols + col], table[(i+1)*ncols + col], frac);
            }
        }
        if (sk5_seconds <= table[0]) return table[col];
        return table[(nrows-1)*ncols + col];
    };

    p.r400  = interp(&track_table[0][0], track_table_rows, 8, 1);
    p.r600  = interp(&track_table[0][0], track_table_rows, 8, 2);
    p.r800  = interp(&track_table[0][0], track_table_rows, 8, 3);
    p.r1000 = interp(&track_table[0][0], track_table_rows, 8, 4);
    p.r1200 = interp(&track_table[0][0], track_table_rows, 8, 5);
    p.r1600 = interp(&track_table[0][0], track_table_rows, 8, 6);
    p.r2000 = interp(&track_table[0][0], track_table_rows, 8, 7);

    p.st_mile = interp(&tempo_table[0][0], tempo_table_rows, 7, 1);
    p.mt_mile = interp(&tempo_table[0][0], tempo_table_rows, 7, 2);
    p.lt_mile = interp(&tempo_table[0][0], tempo_table_rows, 7, 3);

    p.mp_mile  = interp(&long_table[0][0], long_table_rows, 5, 1);
    p.hmp_mile = interp(&long_table[0][0], long_table_rows, 5, 2);

    return p;
}

